using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.City;
using CashflowChains.Economy;
using CashflowChains.Empire;
public sealed class MetropolisTests {
 BalanceConfig c;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 EmpireEngine New(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="metropolis"}},_=>true);e.OpenCity(100);e.EnterExistingCity(101);e.EnterMetropolis(102);return e;}
 [Test]public void CompleteCityExistsWhileTheInvestorOwnsNoPropertyAndReceivesNoCityIncome(){var e=New();Assert.AreEqual(2,e.Snapshot.City.Region);Assert.AreEqual(8,e.Snapshot.City.Width);Assert.AreEqual(8,e.Snapshot.City.Height);Assert.IsEmpty(e.Snapshot.City.Properties);Assert.AreEqual(62,CityMetropolis.Buildings.Count(b=>b.X>=0&&b.Y>=0));Assert.AreEqual(2,Enumerable.Range(0,64).Count(n=>CityMetropolis.Vacant(n%8,n/8)));for(int y=1;y<6;y++)for(int x=1;x<6;x++)Assert.NotNull(CityMetropolis.At(x,y));foreach(string art in new[]{"cafe","urban-restaurant","urban-bar","urban-club","urban-home","urban-apartment","urban-hotel"})Assert.IsTrue(CityMetropolis.Buildings.Any(b=>b.Art==art));var r=e.ForecastCity();Assert.Greater(r.Population,80);Assert.AreEqual(r.Population,r.PublicResidents);Assert.AreEqual(0,r.Revenue);Assert.AreEqual(0,r.Bills);Assert.AreEqual(0,r.Net);Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void BuyingAnExistingRentalChangesOwnershipNotThePopulationOrTenantIdentity(){var e=New();var asset=CityMetropolis.At(3,3);var old=CityRegion.Households(1,2).Single(h=>h.PropertyId==asset.Id);int population=e.ForecastCity().Population;long wood=e.Snapshot.Economy.Amount("WOOD");var quote=e.QuoteCityAcquisition(asset.Id);Assert.IsTrue(quote.Unlocked);Assert.IsTrue(quote.Affordable);Assert.Greater(quote.AfterNet,0);e.AcquireCityProperty("deed",asset.Id,103);Assert.AreEqual(120,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(wood,e.Snapshot.Economy.Amount("WOOD"));Assert.AreEqual(population,e.ForecastCity().Population);e.AdvanceCityTo(106);var r=e.ForecastCity();Assert.AreEqual(population,r.Population);Assert.AreEqual(old.Residents,r.PrivateResidents);var owned=e.Snapshot.City.Properties.Single();var family=CityHousing.Occupancy(c.City,new[]{owned},1,false,1,true).Single();Assert.AreEqual(old.Families.SelectMany(f=>f).Select(p=>p.Id),family.Families.SelectMany(f=>f).Select(p=>p.Id));e.AdvanceCityTo(111);Assert.AreEqual(17,e.Snapshot.City.EarnedCashflow);}
 [Test]public void DeedAndSettlementRetriesCannotDuplicateOwnershipOrMoney(){var e=New();var asset=CityMetropolis.At(3,3);e.AcquireCityProperty("one-deed",asset.Id,103);e.AcquireCityProperty("one-deed",asset.Id,104);Assert.AreEqual(1,e.Snapshot.City.Properties.Count);Assert.AreEqual(120,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<InvalidOperationException>(()=>e.AcquireCityProperty("duplicate",asset.Id,104));e.AdvanceCityTo(111);var prior=e.Snapshot;e.AdvanceCityTo(111);Assert.AreEqual(prior.Economy.Amount("CASH"),e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void AWorkingCafeCanBeAcquiredAsTheFirstDealAndConsumesPaidPrivateStock(){var e=New();var asset=CityMetropolis.At(4,3);e.AcquireCityProperty("cafe-deed",asset.Id,103);e.AdvanceCityTo(111);Assert.IsFalse(e.Snapshot.City.Properties.Any(p=>p.Kind=="home"));Assert.Greater(e.Snapshot.City.LastDayRevenue,0);var r=e.ForecastCity();Assert.Greater(r.CoffeeServed,0);Assert.AreEqual(r.CoffeeServed,r.Resources.Single(x=>x.ItemId=="BEANS").Consumed);}
 [Test]public void PublicServicesAndUnlistedShopsCannotBeStolenRebuiltOrMoved(){var e=New();Assert.Throws<InvalidOperationException>(()=>e.AcquireCityProperty("steal-police",1100,103));Assert.Throws<InvalidOperationException>(()=>e.BuildCity("overwrite-city","home",0,0,103));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));var asset=CityMetropolis.At(3,3);e.AcquireCityProperty("home-deed",asset.Id,103);e.AdvanceCityTo(106);Assert.Throws<InvalidOperationException>(()=>e.MoveCityProperty("move-house",1,7,7,107));}
 [Test]public void TransferOwnershipIsPaidAndSurvivesSerialization(){var e=New();var asset=CityMetropolis.At(3,3);e.AcquireCityProperty("deed",asset.Id,103);var restored=JsonUtility.FromJson<EmpireAccount>(JsonUtility.ToJson(e.Snapshot));restored.Validate(c);var bad=JsonUtility.FromJson<EmpireAccount>(JsonUtility.ToJson(e.Snapshot));bad.City.Properties[0].AcquiredFrom=CityMetropolis.At(4,3).Id;Assert.Throws<ArgumentException>(()=>bad.Validate(c));var resumed=new EmpireEngine(c,restored,_=>true);resumed.AdvanceCityTo(111);Assert.AreEqual(1,resumed.Snapshot.City.Properties.Count);Assert.AreEqual(17,resumed.Snapshot.City.EarnedCashflow);}
 [Test]public void EarlierRegionalTradingPromisesSurviveTheDenseCityTransition(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="metropolis-migration"}},_=>true);e.OpenCity(100);e.EnterExistingCity(101);e.BuildCity("rental","home",1,1,102);e.AdvanceCityTo(105);var before=e.CurrentCityDay();e.EnterMetropolis(106);Assert.AreEqual(before.Net,e.CurrentCityDay().Net);Assert.AreEqual(1,e.Snapshot.City.Trading.Region);e.AdvanceCityTo(110);Assert.AreEqual(2,e.Snapshot.City.Region);Assert.AreEqual(1,e.Snapshot.City.Properties.Count);Assert.Greater(e.ForecastCity().Population,80);}
 [Test]public void ExpandedLandExposesEveryNewAddressWithoutErasingTheExistingCity(){var e=New();Assert.AreEqual(2,CityMetropolis.Vacancies(e.Snapshot.City).Count());e.AcquireCityProperty("first",12027,103);e.AdvanceCityTo(28906);Assert.GreaterOrEqual(e.Snapshot.Economy.Amount("CASH"),640);int population=e.ForecastCity().Population;var owned=e.Snapshot.City.Properties.Single().Copy();e.ExpandCity("east-land",true,28907);Assert.AreEqual(10,e.Snapshot.City.Width);Assert.AreEqual(18,CityMetropolis.Vacancies(e.Snapshot.City).Count());Assert.AreEqual(population,e.ForecastCity().Population);Assert.AreEqual(owned.AcquiredFrom,e.Snapshot.City.Properties.Single().AcquiredFrom);Assert.IsTrue(CityMetropolis.Vacancies(e.Snapshot.City).Any(a=>a.X==9&&a.Y==7));Assert.IsFalse(CityMetropolis.Vacancies(e.Snapshot.City).Any(a=>a.X==3&&a.Y==3));}
}
